WITH remaining_keys AS (SELECT region, city FROM stores EXCEPT ALL SELECT region, city FROM stores WHERE city = 'Tokyo'), reconciled AS (SELECT s.* FROM stores s JOIN remaining_keys k ON s.region = k.region AND s.city = k.city) SELECT region, COUNT_IF(region = 'South') AS south_events, BIT_OR(sqft) AS sqft_bit_or, PERCENTILE_APPROX(sqft, 0.5) AS sqft_p50, PERCENTILE_APPROX(sqft, 0.5) AS sqft_p50_2, COUNT_IF(region = 'South') AS south_events_2 FROM reconciled GROUP BY region
